const leads = $input.all().map(item => item.json);

// Total Leads
const totalLeads = leads.length;

// New Leads
const now = new Date();
const last24Hours = new Date(now.getTime() - 24 * 60 * 60 * 1000);

const newLeads = leads.filter(lead => {
  if (!lead.created_at) return false;

  const createdAt = new Date(lead.created_at);
  return createdAt >= last24Hours && createdAt <= now;
}).length;

// Qualified Leads
const qualifiedLeads = leads.filter(
  lead => lead.lead_status === 'Qualified'
).length;

// Converted Leads
const convertedLeads = leads.filter(
  lead => lead.lead_status === 'Converted'
).length;

// Average Lead Score
const averageLeadScore = leads.length
  ? Number(
      (
        leads.reduce(
          (sum, lead) => sum + Number(lead.lead_score || 0),
          0
        ) / leads.length
      ).toFixed(2)
    )
  : 0;

// Count leads by source
const sourceCounts = {};

for (const lead of leads) {
  const source = lead.source || 'Unknown';
  sourceCounts[source] = (sourceCounts[source] || 0) + 1;
}

// Top Lead Source
const sortedSources = Object.entries(sourceCounts)
  .sort((a, b) => b[1] - a[1]);

const topLeadSource = sortedSources.length
  ? sortedSources[0][0]
  : 'N/A';

const topLeadSourceCount = sortedSources.length
  ? sortedSources[0][1]
  : 0;

// Top 5 Leads
const top5Leads = [...leads]
  .sort(
    (a, b) =>
      Number(b.lead_score || 0) -
      Number(a.lead_score || 0)
  )
  .slice(0, 5)
  .map(lead => ({
    name: lead.name,
    company: lead.company,
    lead_score: Number(lead.lead_score || 0),
    lead_status: lead.lead_status,
    source: lead.source
  }));

// Conversion Rate
const conversionRate = totalLeads > 0
  ? Number(((convertedLeads / totalLeads) * 100).toFixed(2))
  : 0;

return [
  {
    json: {
      totalLeads,
      newLeads,
      qualifiedLeads,
      convertedLeads,
      averageLeadScore,
      topLeadSource,
      topLeadSourceCount,
      top5Leads,
      conversionRate
    }
  }
];

const aiOutput = $json.output || '';

const report = `DAILY LEAD REPORT
====================

${aiOutput}

====================
Report generated automatically by n8n.
`;

return [
  {
    json: {
      report
    }
  }
];
